from collections import defaultdict, deque
import math
from heapq import heappush, heappop

def dijkstra(graph, start, n):
    """Perform Dijkstra's algorithm."""
    dist = [math.inf] * n
    visited = [False] * n
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heappop(heap)
        if visited[u]:
            continue
        visited[u] = True

        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heappush(heap, (dist[v], v))

    return dist

def find_shortest_path(graph, start, end, operations, length):
    queue = [(0, start, 1)]
    visited = set()
    visited.add(start)

    while queue:
        d, u, steps = heappop(queue)
        if u == end:
            return (d, d + operations)

        for v in graph[u]:
            if v in visited or v > length:
                continue
            visited.add(v)
            h_cost = d + v
            v_cost = d + (v ^ ((v ^ 1) & (2 ** operations - 1))) & 65535
            h_heap = dist[(n - 1) for l in (h_cost, v_cost) for n in l]
            v_heap = dist[v_cost]
            key = (min(v_cost, h_cost), (0,) + (u,))
            if h_heap == v_heap:
                key = (min(h_cost, v_cost), (v,))
            heapq.heappush(queue, (key, u))

    return (-1, [])

def main():
    n, m = map(int, input().split())
    graph = defaultdict(list)

    for _ in range(m):
        u, v, x = map(int, input().split())
