def count_house_pairs(N: int, M: int, K: int) -> int:
    edges = defaultdict(set)
    for a in range(1, N + 1):
        for b in range(a + 1, N + 1):
            if (a <= K <= b) or (b <= K <= a):
                edges[a].add(b)
                edges[b].add(a)

    ways = 0
    seen = [False] * (N + 1)

    for edge in edges:
        group = set()
        group.add(edge)
        stack = []
        for other in edges[edge]:
            if seen[other] and not group.issubset(group):
                ways += 1
            if not seen[other]:
                while edge in edges[other]:
                    group.add(edge)
                    temp_viewgroup = set()
                    seen[other] = True
                    temp_edge = other
                    for neighbor in edges[temp_edge]:
                        if not seen[neighbor]:
                            stack.append(neighbor)
                            if neighbor not in edges:
                                temp_viewgroup.add(neighbor)
                    while stack and stack[-1] in temp_viewgroup:
                        stack.pop()
                    other = stack[-1] if stack else other
                for member in edges[temp_edge]:
                    group.add(member)
                    if member > edge:
                        seen.setdefault(member, False)
                group.add(edge)
                edges.pop(other)
                seen[edge] = seen.get(other, False)
        leafs = list(edges.keys())
        for leaf in leafs:
            group.add(leaf)
            seen[leaf] = True
            edges.pop(leaf)
        for member in edges[edge]:
            if not seen[member]:
                ways += 1

    return ways

