from collections import defaultdict

def find_parent(parent_set, x):
    if parent_set[x] != x:
        parent_set[x] = find_parent(parent_set, parent_set[x])
    return parent_set[x]

def consolidate(parent_set, rank, x, y):
    root_x = find_parent(parent_set, x)
    root_y = find_parent(parent_set, y)
    if rank[root_x] < rank[root_y]:
        parent_set[root_x] = root_y
    elif rank[root_x] > rank[root_y]:
        parent_set[root_y] = root_x
    else:
        parent_set[root_y] = root_x
        rank[root_x] += 1

def can_form_game(group_size, acquaintances):
    if group_size == 1:
        return True
    for x in group_size:
        for y in group_size:
            if x != y:
                for pair in acquaintances:
                    if pair[0] > x and pair[1] > y:
