        group_size[consolidated_group % k] = max(0, group_size[consolidated_group % k])
        i += 1

    total_options = n // 2
    for group_size in group_size:
        total_options *= max(0, group_size - 1)
    total_options //= 2  # Because each pair gives way to two outcomes

