def minimum_code_depth(tree, node, parent):
    min_depth = 200000
    for child in tree[node]:
        if child != parent:
            depth = minimum_code_depth(tree, child, node)
            if depth < min_depth:
                min_depth = depth
    return min_depth

def connect_minimums(tree, node, depth, child):
    or_parent = 0
    for i in range(20):
        if node ^ child in tree:
            if tree[node ^ child][child]:
                if i < depth:
                    or_parent |= (2 ** (20 - i - 1))
    return or_parent

def count_tree_classes(tree, node):
    if node in tree:
        res = 1
        for child in tree[node]:
            res += count_tree_classes(tree, child)
        tree.pop(node)
        return res
    return 1

def quantify(tree):
    if len([l for l in tree if len(l) > 0]) > 2:
        return [q for q in tree if len(q) > 0]
    return [q[0] for q in tree] + [q[1] for q in tree]

def minimize_connected(tree, node):
