    classes = count_tree_classes(tree, non_empty_trees[0][0])
    if classes < 3:
        depth = 0
        for child in non_empty_trees:
            depth = max(depth, count_code_depth(tree, child, non_empty_trees[0][0]))
        return depth
    else:
        return 1

def find_tree_class(tree, state):
