from collections import defaultdict

def find_shortest_path(n, m, edges, s, t):
    # Create a graph
    graph = defaultdict(list)
    for u, v, weight in edges:
        graph[u].append((v, weight))
        graph[v].append((u, weight))

    # Bellman-Ford algorithm to find the shortest path
    def bellman_ford(start, end):
        # Initialize distances and predecessors
        dist = [float('inf')] * n
        dist[start] = 0
        predecessors = [-1] * n

        # Relax edges repeatedly
        for _ in range(n - 1):
            for u in range(n):
                for v, weight in graph[u]:
                    if dist[u] + weight < dist[v]:
                        dist[v] = dist[u] + weight
                        predecessors[v] = u

        # Check for negative weight cycles
        for u in range(n):
            for v, weight in graph[u]:
                if dist[u] + weight < dist[v]:
                    raise ValueError("Graph contains a negative weight cycle.")

        # Check if end is reachable from start
        if dist[end] == float('inf'):
            return -1
        else:
            return dist[end]

    # Get shortest path length and number of vertices
    path_length = bellman_ford(s, t)
    if path_length == -1:
        return -1
    else:
        path = [s]
        current = s
        while current != t:
            for v, weight in graph[current]:
                if weight == path_length:
                    path.append(v)
                    current = v
                    break
        return path_length, len(path), path

