def to_binary_with_padding(n, width):
    """Convert decimal n to binary, padded with leading zeros to width characters."""
    return format(n, '0{}b'.format(width))

def have_similar_binary(a1, a2, width):
    """Check if two numbers have the same number of 1's in their binary representation."""
    return to_binary_with_padding(a1, width) == to_binary_with_padding(a2, width)

def find_similar_xor(binary_a, binary_sum=0, max_xor=2**30-1):
    """Find a non-negative integer x such that (`a_i` ⊕ x)`'s binary representation has the same number of 1's."""
    for i in range(max_xor):
        if have_similar_binary(binary_a, to_binary_with_padding(binary_sum + i, 7)):
            return i

def can_make_all_similar(a):
    """Check if it's possible to make all elements of the array `a` similar through a bitwise XOR operation."""
    if set(a) == {0}:  # Only zero is considered "similar" by this definition
        return False

    sum_a = 0
    for a_i in a:
        sum_a ^= a_i

    # No way to make all elements similar if there's a number that's not similar to zero
    if sum_a ^ a[0] != 0:
        return False

    # Iterate through all Xors, find one that makes them all the same
    could_make_all_similar = find_similar_xor(sum_a)

    if could_make_all_similar is not None:
        return True, could_make_all_similar

    # If no suitable bit is found, there is no way to make the array of numbers (a) all similar
    return False, None

