from collections import defaultdict

class Graph:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, d):
        self.adj[u].append((v, d))
        self.adj[v].append((u, d))

    def remove_edge(self, u, v):
        self.adj[u] = [(w, e) for w, e in self.adj[u] if w != v]
        self.adj[v] = [(w, e) for w, e in self.adj[v] if w != u]

    def dijkstra(self, s):
        dist = [float('inf')] * self.n
        dist[s] = 0
        queue = [(0, s)]
        heapq.heapify(queue)

        while queue:
            d, u = heapq.heappop(queue)
            if d > dist[u]:
                continue
            for v, w in self.adj[u]:
                if dist[u] + w + d < dist[v]:
                    dist[v] = dist[u] + w + d
                    heapq.heappush(queue, (dist[v], v))

        return dist

