        return x
    parent[x] = find_set(parent[x], parent)
    return parent[x]

def union_sets(x, y, parent):
    x, y = find_set(x, parent), find_set(y, parent)
    if x > y:
        x, y = y, x
    parent[y] = x

def is_in_groups(x, y, groups):
