def find_ancestor(n, queries):
    parent = [i for i in range(n)]
    rank = 1

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rank_x, rank_y = rank(find(x)), rank(find(y))
        if rank_x == rank_y:
            parent[find(x)] = find(y)
        else:
            parent[find(x)] = rank_x + 1 if rank_x > rank_y else rank_y + 1

    root, ans = None, []
