import heapq

def remove_edges_greedy(connections, edges):
    edges.sort()
    degree = [0] * (connections + 1)

    for u, v in edges:
        degree[u] += 1
        degree[v] += 1

    connections_count = 0
    remaining_edges = [(-(d + 1), u, (d % 2) == 0, v) for u, d in enumerate(degree) if d + 1]

    while remaining_edges:
        weights, u, is_odd, v = heapq.heappop(remaining_edges)
        if is_odd:
            degree[v] += 1
        connections_count += 1

        if degree[u] % 2 != 0:
            degree[v] += (-1)
        else:
            degree[v] -= 1

        if degree[v] < 0:
            if degree[v] + 1 <= degree[u]:
                heapq.heappush(remaining_edges, (-(degree[u] + degree[v] + 1), (degree[u] + degree[v] + 1) % 2, u, v))
            else:
                heapq.heappush(remaining_edges, (-(degree[u] + degree[v]), (-1, u, -1, v)))

