def find_best_expression(n, nums, operations):
    operations = list(operations)
    indices = list(range(n))
    for i in range(n - 1):
        for j in indices:
            for k in range(j + 1, n):
                partial_expr = nums[j] + nums[k]
                expr_len = j + k + 1
                potential_expr = nums[j:k + 1]
                potential_operations = operations.copy()
                potential_operations += potential_expr[-1]
                best_result = evaluate_expression(nums, potential_operations[::-1])
                partial_expr_node = nums[j:k + 1:2]
                if best_result < evaluate_expression(partial_expr_node, potential_operations):
