from collections import defaultdict

def miniMaxTreeDist(n, edges):
    # Build adjacency list
    graph = defaultdict(list)
    for start, end, weight in edges:
        graph[start].append((end, weight))
        graph[end].append((start, weight))

    # Function to calculate weighted shortest path
    def find_min_max_dist(d, *max_weights):
        paths_to_d = {}
        for vertices, cvertices in graph.items():
            if d == 1:
                continue
            path_to_root = defaultdict(list)
            if d < len(cvertices):
                path_to_root[1].append(cvertices[d])
            for i, edge in enumerate(cvertices):
                if i == d:
                    continue
                updated_path = edge[1] + path_to_root[i]
                paths_to_d[tuple(updated_path)] = path_to_root[i] + edge[1]
            m_vertices = len(cvertices) - d
            if not paths_to_d[(1,)][:min(m_vertices, cvertices[d])]:
                for prev_path, weights in remove(d, *max_weights):
                    if str(paths_to_d[tuple(prev_path)]) not in paths_to_d:
                        paths_to_d[str(paths_to_d[tuple(prev_path)])] = []
                    paths_to_d[str(paths_to_d[tuple(prev_path)])].append((prev_path, min(*weights)))
            for path in path_to_root:
                weight = 0
                for i in path[:-1]:
                    for j in path[::-1][i:][::-1]:
                        weight += paths_to_d[str(paths_to_d[tuple(path[:i])])] + paths_to_d[str(paths_to_d[tuple(path[i+1:])])]
                if paths_to_d.get(str(path[:-1]), []):
                    weight += paths_to_d[str(path[:-1])][-1][-1]
                paths_to_d[tuple(path)] = weight

        return [paths_to_d[str(tuple(path))] for path in paths_to_d.keys()]

    # Remove a weight histogram from an index
    def remove(index, *weights):
        n = len(weights)
        removed_weights = sorted(range(n), key=lambda i: weights[i], reverse=True)[:index]
        max_weights = sorted(weights, reverse=True)
        flatten = all([(j + 1, k + 1, max_weights[j]) for j, k in enumerate(removed_weights)])

        for left, right, weight in flatten:
            if left == 0:
                continue
            for group in find_min_max_dist(n, *max_weights):
                yield tuple(group)

    return find_min_max_dist(0, *max(get(graph.items()), key=lambda x: (len(x[1]), x[0])))

