def modulo_power(a, b, mod):
    result = 1
    a = a % mod
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % mod
        b = b // 2
        a = (a * a) % mod
    return result

def process_c_tuples(c00, c01, c10, c11):
    results = [0] * 10001
    total = c00 + c01 + c10 + c11
    if total == 0:
        return c00, c01, c10, c11
    if c00 == 0:
        if c10 == 0:
            if c11 == 0:
                return results[0], 1, 1, c11
            else:
                return results[0] % 1000000007, 1, 2, 1
        elif c11 == 0:
            return results[0] % 1000000007, 0, 2, 1
    elif c01 == 0:
        if c00 == 0:
            return results[0], c01, 2, 1
        else:
            return results[1] % 1000000007, c01, 3, 1
    elif c10 == 0:
        if c11 == 0:
            return results[0], c01, 0, 1
        elif c00 == 0:
            return results[1], c01, 2, 1
    elif c11 == 0:
        return results[0], c01, 0, 2
    results[0], results[1], results[2], results[3] = \
        modulo_power(2, total, 1000000007), \
        results[0], \
        modulo_power(2, c10, 1000000007) + modulo_power(2, c11, 1000000007), \
        results[1]
    if total == 1:
        results[0], results[1], results[2] = results[1] % 1000000007, results[0], 1, 0
    return results[0], results[1], results[2], results[3]

def count_possible_numbers(A, B, counts):
    unusual_counts = process_c_tuples(counts[0] % 1000000007, counts[1] % 1000000007, counts[2] % 1000000007, counts[3] % 1000000007)
    total_substrings = unusual_counts[0] + unusual_counts[1] + unusual_counts[2]
    return modulo_power(2, total_substrings, 1000000007) % 1000000007

