import sys

class Graph:
    def __init__(self, vertices):
        self.V = vertices
        self.graph = [[0 for _ in range(vertices)] for _ in range(vertices)]

def dijkstra(graph, src):
    q = [src]
    distances = [0] + [float('inf')] * (graph.V - 1)
    prev = [-1] * graph.V

    while q:
        u = q.pop(0)
        for v, w in graph.graph[u]:
            if distances[v] > w + distances[u]:
                distances[v] = w + distances[u]
                prev[v] = u
                q.append(v)

    return distances, prev

def find_path(prev, s, t):
    path = [t]
    while t != s:
        t = prev[t]
        path.append(t)
    path.reverse()
    return path

def solve(n, m, graph):
    edges = list(zip(range(1, n), range(1, n), [2 ** e for e in range(m)]))
    result = 0
    for i in range(n):
        dist, prev = dijkstra(graph, i)
        if i == n - 1:
            result = max(result, (dist[-1] - dist[0]) % 1000000007)
        for j in range(n):
            if j < i and j > i + 1 and dist[j] < dist[j - 1]:
                u, v, weight = edges[j]
                result = max(result, weight * (dist[i] - dist[i - 1]) % 1000000007)
            if j < i and j > i - 1 and dist[j] < dist[j + 1]:
                u, v, weight = edges[j]
                result = max(result, weight * (dist[i] - dist[i + 1]) % 1000000007)
            if i == n - 1 and j > i:
                if dist[i] < dist[j]:
                    result = max(result, (dist[j] - dist[i]) % 1000000007)

    return result % 1000000007 if result < 1000000007 else -1

